function minSteps(n) {
  let steps = 0;
  let remaining = n;

  for (let factor = 2; factor * factor <= remaining; factor++) {
    while (remaining % factor === 0) {
      steps += factor;
      remaining /= factor;
    }
  }
  if (remaining > 1) {
    steps += remaining;
  }
  return steps;
}

