function minSteps(n) {
  // dp[i]: fewest steps to reach i characters; the last copy happened at some divisor j of i.
  const dp = new Array(n + 1).fill(Infinity);
  dp[1] = 0;
  for (let i = 2; i <= n; i++) {
    for (let j = 1; j < i; j++) {
      if (i % j === 0) dp[i] = Math.min(dp[i], dp[j] + i / j);
    }
  }
  return dp[n];
}

